import React from 'react';
import { useNavigate } from 'react-router-dom';

import './../../adaptation.css';
import './../../App.css';
import './Main.css';
import './Tabs.css';

import InfoBlocks from './InfoBlocks/InfoBlocks';
import ImportanceBlocks from './importance-block/importance-blocks';
import HowItWorks from './how-it-works/how-it-work';
import YearByYear from './year-by-years/year-by-year';

const Main = () => {
  const navigate = useNavigate();

  const handleMatrixButtonClick = () => {
    navigate('/matrix');
  };

  return (
    <React.Fragment>
      <div className="container main" id="home">
        <section className="main-left">
          <div className="main-left_text">
            <h1>Онлайн расчет <span className="highlight">Матрицы Судьбы</span> с подробной расшифровкой</h1>
            <p>Получите расчет вашей Матрицы Судьбы! Узнайте совместимость, детскую, финансовую матрицу и матрицу личного бренда с полной автоматической расшифровкой и рекомендациями от психолога. Улучшите свою жизнь, работая с энергиями вашей матрицы.</p>
          </div>

          <div className="tabs">
            <button className="btn" onClick={handleMatrixButtonClick}>
              Рассчитать Матрицу Судьбы
            </button>
            <button className="btn">Финансовая</button>
            <button className="btn">Совместимость</button>
            <button className="btn">Детская</button>
          </div>
        </section>

        <section className="main-right">
          <img src={process.env.PUBLIC_URL + '/assets/img/main-right/background-2.webp'} alt="background-2" className="photo" />
        </section>
      </div>

      <InfoBlocks />
      <ImportanceBlocks />
      <HowItWorks />
      <YearByYear />
    </React.Fragment>
  );
};

export default Main;